// ตรวจว่า "ตำแหน่งว่าง" ถูกปล่อยค้างหรือไม่ (กติกาห้ามปล่อยว่าง ถ้ามีผู้ผ่านเงื่อนไข)
// พร้อมสรุป Audit Log ล่าสุดของระบบ 1 แตก 5 (ตรวจสอบย้อนหลังได้)
const s = $json || {};
const sm = s.summary || {};
const logs = Array.isArray(s.logs) ? s.logs : [];
const stuckVacancies = (sm.vacancies || 0) > 0 && (sm.readyCandidates || 0) === 0;
const lastRun = s.lastRun || null;
const recentCuts = logs.filter(function (l) { return l.action === 'net1x5.cut_member'; }).length;
const recentPromotions = logs.filter(function (l) { return l.action === 'net1x5.promote_member'; }).length;
const stalled = logs.filter(function (l) { return l.action === 'net1x5.vacancy_queued'; }).length;
return [{ json: {
  workflow: '1x5 Autopilot 05 · audit watch',
  ok: s.ok !== false,
  period: s.period || null,
  total: sm.total || 0,
  failed: sm.failed || 0,
  vacancies: sm.vacancies || 0,
  readyCandidates: sm.readyCandidates || 0,
  stuckVacancies: stuckVacancies,
  recentCuts: recentCuts,
  recentPromotions: recentPromotions,
  stalledVacancyLogs: stalled,
  lastRunAt: lastRun ? lastRun.startedAt : null,
  lastRunCut: lastRun ? lastRun.cut : 0,
  lastRunPromoted: lastRun ? lastRun.promoted : 0,
  alertText: stuckVacancies
    ? '⚠️ มีตำแหน่งว่างที่ยังไม่มีผู้มีคุณสมบัติครบ (' + (sm.vacancies || 0) + ' ตำแหน่ง) — ระบบจะตรวจซ้ำทุก 15/30 นาที และพยายามเติมอัตโนมัติ'
    : 'ปกติ: ไม่มีตำแหน่งว่างที่ปล่อยค้างเกินกติกา',
  checkedAt: new Date().toISOString()
} }];
